/**
 * A server-paged, server-sorted record table. Page and sort live in the URL (`useQueryState`), so
 * Back, Forward and a copied link restore the view; `keepPrevious` keeps the current page on
 * screen while the next one loads.
 */
import { createRoot } from 'react-dom/client';
import { SurfaceApp, Table, parseAsEnum, parseAsInteger, parseAsString, useQuery, useQueryState } from '@cynap/surface-sdk';

import './styles.css';

/** The org's entity type and the columns to show. Replace both. */
const ENTITY_TYPE = 'REPLACE_WITH_ENTITY_TYPE';
const COLUMNS = [
  { accessorKey: 'name', header: 'Name' },
  { accessorKey: 'stage', header: 'Stage' },
  { accessorKey: 'updated_at', header: 'Updated' },
];
const PAGE_SIZE = 25;

type Row = Record<string, unknown>;
type Page = { rows: Row[]; total: number };

const isRecord = (value: unknown): value is Row => typeof value === 'object' && value !== null && !Array.isArray(value);

function readPage(payload: unknown): Page | null {
  if (!isRecord(payload) || !Array.isArray(payload.rows)) return null;
  const meta = isRecord(payload.meta) ? payload.meta : {};
  const rows = payload.rows.filter(isRecord);
  return { rows, total: typeof meta.total === 'number' ? meta.total : rows.length };
}

function Records() {
  const [page, setPage] = useQueryState('page', parseAsInteger, { defaultValue: 1, history: 'push' });
  const [sort, setSort] = useQueryState('sort', parseAsString);
  const [direction, setDirection] = useQueryState('dir', parseAsEnum(['asc', 'desc'] as const), { defaultValue: 'asc' });
  const current = Math.max(1, page ?? 1);
  const records = useQuery(
    'knowledge_query_data',
    {
      tool: 'knowledge_advanced_query',
      params: {
        entity_type: ENTITY_TYPE,
        limit: PAGE_SIZE,
        offset: (current - 1) * PAGE_SIZE,
        ...(sort ? { sort_by: sort, sort_order: direction ?? 'asc' } : {}),
      },
    },
    { parse: readPage, keepPrevious: true }
  );

  return (
    <main className="tpl-page">
      <Table
        columns={COLUMNS}
        data={records.data?.rows ?? null}
        isLoading={records.state === 'loading'}
        error={records.state === 'error' ? new Error('The records could not be loaded.') : null}
        onRetry={records.refetch}
        pagination={{ page: current, pageSize: PAGE_SIZE, total: records.data?.total ?? 0 }}
        onPageChange={(next) => setPage(next)}
        onSortChange={(next) => {
          setSort(next ? next.field : null);
          setDirection(next ? next.direction : null);
          setPage(1);
        }}
      />
    </main>
  );
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'record-table', version: '1.0.0' }}>
      <Records />
    </SurfaceApp>
  );
}

